SELECT DISTINCT m.entry_id, m.formula, s.prototype, s.space_group_number, s.crystal_system
FROM material_entry m
JOIN structure s ON s.entry_id = m.entry_id
WHERE EXISTS (
  SELECT 1 FROM composition c_1 WHERE c_1.entry_id = m.entry_id AND c_1.element = 'Rh'
) AND EXISTS (
  SELECT 1 FROM composition c_2 WHERE c_2.entry_id = m.entry_id AND c_2.element = 'Al'
)
LIMIT 10000;
